"""GateDataset — loads labeled frames generated by scripts/gen_dataset.py.

Label file format (labels.jsonl): one JSON object per line:
  {
    "file":          "images/frame_000000.jpg",
    "gate_detected": true,
    "cx":            0.52,    # gate center x, normalized [0, 1]
    "cy":            0.48,    # gate center y, normalized [0, 1]
    "bw":            0.14,    # bbox width, normalized [0, 1]
    "bh":            0.18,    # bbox height, normalized [0, 1]
    "area":          43008.0, # bounding box area in original-res pixels
    "scale":         0.21     # mock sim gate scale at capture time
  }

Usage:
    ds = GateDataset("data/gate_dataset", input_h=128, input_w=160, augment=True)
    loader = DataLoader(ds, batch_size=64, shuffle=True, num_workers=4)
    images, labels = next(iter(loader))
    # images: (B, 3, H, W) float32 in [0, 1]
    # labels: (B, 5) float32 — [det, cx, cy, bw, bh]
"""
from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Optional

import cv2
import numpy as np
import torch
from torch.utils.data import Dataset


class GateDataset(Dataset):
    """PyTorch Dataset for gate detection frames.

    Args:
        root:     Path (or list of paths) to dataset root(s).
                  Each root must contain images/ and labels.jsonl.
                  Multiple roots are merged — no file copying required.
        input_h:  Resize height for model input.
        input_w:  Resize width for model input.
        augment:  If True, apply random photometric augmentation.
        split:    "all" | "train" | "val" — val is last 15% of data.
    """

    def __init__(
        self,
        root: str | Path | list,
        input_h: int = 128,
        input_w: int = 160,
        augment: bool = False,
        split: str = "all",
    ):
        self.input_h = input_h
        self.input_w = input_w
        self.augment = augment

        # Support single root or list of roots
        roots = [root] if not isinstance(root, list) else root
        roots = [Path(r) for r in roots]

        all_rows = []
        for r in roots:
            labels_path = r / "labels.jsonl"
            if not labels_path.exists():
                raise FileNotFoundError(f"labels.jsonl not found in {r}")
            with open(labels_path) as f:
                for line in f:
                    if line.strip():
                        row = json.loads(line)
                        # Store absolute file path so we don't need the root later
                        row["_abs_file"] = str(r / row["file"])
                        all_rows.append(row)

        # Keep root for backward compat (single root case)
        self.root = roots[0]

        # Deterministic split: last 15% → val
        n_val = max(1, int(len(all_rows) * 0.15))
        if split == "train":
            self.rows = all_rows[:-n_val]
        elif split == "val":
            self.rows = all_rows[-n_val:]
        else:
            self.rows = all_rows

        self._rng = np.random.default_rng(0)

        # Cache all images in RAM — eliminates disk I/O after first load.
        # 75K images at 128×160×3 uint8 ≈ 4.6 GB. Use cache=True only if RAM allows.
        # With resize to model input size first, each image is 128×160×3 = 61 KB → ~4.6 GB total.
        # Default: cache resized images (much smaller than originals).
        print(f"  Loading {len(self.rows)} images into RAM...", end=" ", flush=True)
        self._cache: list = [None] * len(self.rows)
        for i, row in enumerate(self.rows):
            img_path = row.get("_abs_file", str(self.root / row["file"]))
            img_bgr = cv2.imread(str(img_path))
            if img_bgr is None:
                img_bgr = np.zeros((self.input_h, self.input_w, 3), dtype=np.uint8)
            img_rgb = cv2.cvtColor(img_bgr, cv2.COLOR_BGR2RGB)
            self._cache[i] = cv2.resize(img_rgb, (self.input_w, self.input_h))
        print("done.", flush=True)

    def __len__(self) -> int:
        return len(self.rows)

    def __getitem__(self, idx: int) -> tuple[torch.Tensor, torch.Tensor]:
        row = self.rows[idx]
        img_rgb = self._cache[idx].copy()

        cx = float(row["cx"])
        cy = float(row["cy"])

        # Augmentation: geometric (flip) + photometric — applied per-epoch so
        # the model sees different variations on each pass through the data.
        if self.augment:
            img_rgb, cx = self._augment(img_rgb, cx)

        # (H, W, 3) uint8 → (3, H, W) float32 in [0, 1]
        tensor = torch.from_numpy(np.ascontiguousarray(img_rgb)).permute(2, 0, 1).float() / 255.0

        # Label: [det, cx, cy, bw, bh]
        if row["gate_detected"]:
            label = torch.tensor(
                [1.0, cx, cy, row["bw"], row["bh"]], dtype=torch.float32
            )
        else:
            label = torch.tensor([0.0, 0.5, 0.5, 0.0, 0.0], dtype=torch.float32)

        return tensor, label

    # ------------------------------------------------------------------
    # Augmentation
    # ------------------------------------------------------------------

    def _augment(self, img: np.ndarray, cx: float) -> tuple[np.ndarray, float]:
        """Photometric + geometric augmentation. Returns (augmented_img, new_cx).

        Geometric:
          - Horizontal flip (50%) — cx becomes 1-cx; bw/bh unchanged

        Photometric (applied stochastically):
          - Brightness/contrast, Gaussian noise, gamma, motion blur
          - Color jitter (hue/saturation) — critical for gate color generalization
          - JPEG artifacts (matches real sim UDP stream)
          - Cutout (2 patches) — forces model to use whole gate shape
        """
        rng = self._rng

        # Horizontal flip — properly corrects cx label
        if rng.random() < 0.5:
            img = img[:, ::-1, :].copy()
            cx = 1.0 - cx

        # Brightness + contrast
        if rng.random() < 0.7:
            alpha = float(rng.uniform(0.6, 1.4))
            beta  = float(rng.uniform(-40, 40))
            img = np.clip(img.astype(np.float32) * alpha + beta, 0, 255).astype(np.uint8)

        # Color jitter — most important for gate color generalization
        if rng.random() < 0.6:
            hsv = cv2.cvtColor(img, cv2.COLOR_RGB2HSV).astype(np.float32)
            hsv[:, :, 0] = (hsv[:, :, 0] + rng.uniform(-20, 20)) % 180
            hsv[:, :, 1] = np.clip(hsv[:, :, 1] * rng.uniform(0.4, 1.6), 0, 255)
            img = cv2.cvtColor(hsv.astype(np.uint8), cv2.COLOR_HSV2RGB)

        # Gaussian noise
        if rng.random() < 0.5:
            std = float(rng.uniform(3, 25))
            noise = rng.normal(0, std, img.shape)
            img = np.clip(img.astype(np.float32) + noise, 0, 255).astype(np.uint8)

        # Gamma
        if rng.random() < 0.4:
            g = float(rng.uniform(0.5, 2.0))
            table = np.array([(i / 255.0) ** (1.0 / g) * 255
                               for i in range(256)], dtype=np.uint8)
            img = cv2.LUT(img, table)

        # Motion blur
        if rng.random() < 0.3:
            k = int(rng.choice([3, 5, 7]))
            direction = int(rng.integers(0, 2))
            kernel = np.zeros((k, k), dtype=np.float32)
            if direction == 0:
                kernel[k // 2, :] = 1.0 / k
            else:
                kernel[:, k // 2] = 1.0 / k
            img = cv2.filter2D(img, -1, kernel)

        # JPEG artifacts — sim streams real JPEG frames
        if rng.random() < 0.4:
            q = int(rng.integers(40, 85))
            _, enc = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, q])
            img = cv2.imdecode(enc, cv2.IMREAD_COLOR)
            img = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)

        # Cutout — 1-2 random patches, mean-filled
        if rng.random() < 0.5:
            H, W = img.shape[:2]
            mean_val = img.mean(axis=(0, 1))
            for _ in range(int(rng.integers(1, 3))):
                rw = int(rng.uniform(0.05, 0.2) * W)
                rh = int(rng.uniform(0.05, 0.2) * H)
                x = int(rng.integers(0, max(1, W - rw)))
                y = int(rng.integers(0, max(1, H - rh)))
                img = img.copy()
                img[y:y + rh, x:x + rw] = mean_val

        return img, cx


# ---------------------------------------------------------------------------
# Stats helper
# ---------------------------------------------------------------------------

def dataset_stats(root: str | Path) -> dict:
    """Return quick stats about a dataset folder."""
    root = Path(root)
    labels_path = root / "labels.jsonl"
    with open(labels_path) as f:
        rows = [json.loads(line) for line in f if line.strip()]

    n_total = len(rows)
    n_pos = sum(1 for r in rows if r["gate_detected"])
    n_neg = n_total - n_pos
    return {
        "total": n_total,
        "positive": n_pos,
        "negative": n_neg,
        "pos_frac": n_pos / max(n_total, 1),
    }
